content.content:
1	import { cycleOption } from "../lib/cycle_option";
2	import { DOM_IDS, findElement, requireElement } from "../lib/dom_ids";
3	import type { PlayerEventDetailValue } from "../lib/events";
4	import { defineHook } from "../lib/hook";
5	import { watchNavAck } from "../lib/nav_ack";
6	import { PersistedRecord } from "../lib/persisted_record";
7	import { attachPlayerEventBuffer } from "../lib/player_event_buffer";
8	import {
9	  attachProgressBuffer,
10	  type ProgressBuffer,
11	  readLastPosition,
12	  writeLastPosition,
13	} from "../lib/progress_buffer";
14	import { readerSettings } from "../lib/reader_settings_store";
15	import { scrollFollow } from "../lib/scroll_follow";
16	import { attachScrubber, fractionAt } from "../lib/scrubber";
17	import {
18	  isJsonObject,
19	  type JsonValue,
20	  parseWordTimings,
21	  type WordTiming,
22	  wordSelector,
23	} from "../lib/types";
24	import { attachWordMenu } from "./word_menu";
25	
26	interface AudioPlayerDataset {
27	  audioUrl: string;
28	  timingsUrl: string;
29	  initialPosition?: string;
30	  bookId?: string;
31	  bookTitle?: string;
32	  chapterTitle?: string;
33	  chapterId?: string;
34	  nextChapterId?: string;
35	  nextAudioUrl?: string;
36	  nextTimingsUrl?: string;
37	  nextChapterTitle?: string;
38	  prevChapterId?: string;
39	  prevAudioUrl?: string;
40	  prevTimingsUrl?: string;
41	  prevChapterTitle?: string;
42	}
43	
44	interface PlayerPrefs {
45	  readonly speed: number;
46	  readonly volume: number;
47	  readonly collapsed: boolean;
48	}
49	
50	const PLAYER_PREFS_DEFAULTS: PlayerPrefs = Object.freeze({
51	  speed: 1,
52	  volume: 1,
53	  collapsed: false,
54	});
55	
56	const PLAYER_PREFS_KEY = "readaloud-player-prefs";
57	
58	const SPEEDS = [0.5, 0.75, 1, 1.25, 1.5, 1.75, 2] as const;
59	
60	const POSITION_REPORT_INTERVAL_MS = 5000;
61	// Diagnostic heartbeat cadence while playing. Each heartbeat carries the
62	// wall-clock and audio-position deltas since the previous one — on a
63	// healthy player they match (scaled by playbackRate); divergence or a gap
64	// in the series is direct evidence of background throttling/suspension.
65	const HEARTBEAT_INTERVAL_MS = 30_000;
66	const SKIP_SECONDS = 10;
67	const AUTO_SCROLL_GRACE_MS = 800;
68	
69	// Play/pause button glyphs. The LV template renders ▶ (as &#9654;) as the
70	// static default; the hook overwrites textContent on every audio play/pause.
71	const PLAY_GLYPH = "▶";
72	const PAUSE_GLYPH = "❚❚";
73	
74	function coercePlayerPrefs(raw: JsonValue): Partial<PlayerPrefs> {
