111	function findActiveWord(
112	  timings: ReadonlyArray<WordTiming>,
113	  ms: number,
114	): number {
115	  let idx = -1;
116	  let lo = 0;
117	  let hi = timings.length - 1;
118	  while (lo <= hi) {
119	    const mid = (lo + hi) >>> 1;
120	    const t = timings[mid];
121	    if (!t) break;
122	    if (ms >= t.startMs && ms < t.endMs) {
123	      idx = mid;
124	      break;
125	    } else if (ms < t.startMs) {
126	      hi = mid - 1;
127	    } else {
128	      idx = mid;
129	      lo = mid + 1;
130	    }
131	  }
132	  if (idx >= 0 && idx < timings.length - 1) {
133	    const next = timings[idx + 1];
134	    if (next && ms >= next.startMs) idx += 1;
135	  }
136	  return idx;
137	}
