1213	        if (currentWordIndex >= 0 && textContainer) {
1214	          const el = textContainer.querySelector<HTMLElement>(
1215	            wordSelector(currentWordIndex),
1216	          );
1217	          el?.scrollIntoView({ behavior: "smooth", block: "center" });
1218	        }
1219	      });
1220	    }
1221	
1222	    if (textContainer && "IntersectionObserver" in window) {
1223	      intersectionObserver = new IntersectionObserver(
1224	        (entries) => {
1225	          for (const entry of entries) {
1226	            if (entry.isIntersecting && scrollFollow.get().autoScrollPaused) {
1227	              scrollFollow.resume();
1228	            }
1229	          }
1230	        },
1231	        { threshold: 0.5 },
1232	      );
1233	      ctx.onDestroy(() => intersectionObserver?.disconnect());
1234	    }
1235	
1236	    ctx.bindStore(scrollFollow, (s) => {
1237	      if (!resyncBtn) return;
1238	      resyncBtn.classList.toggle("hidden", !s.autoScrollPaused);
1239	    });
1240	
1241	    // Word menu actions
1242	    ctx.on(window, "word-action", (detail) => {
1243	      if (detail.kind === "play") seekToWordIndex(detail.index);
1244	    });
1245	
1246	    // Speed badge cycle
1247	    if (speedBadge) ctx.on(speedBadge, "click", () => cycleSpeed("up"));
1248	
1249	    // Keyboard-shortcut events
1250	    ctx.on(window, "audio:toggle-playback", togglePlayback);
1251	    ctx.on(window, "audio:toggle-mute", () => {
1252	      audio.muted = !audio.muted;
1253	    });
1254	    ctx.on(window, "audio:change-speed", ({ direction }) =>
1255	      cycleSpeed(direction),
1256	    );
1257	
1258	    // Manual chapter nav (floating-pill buttons + keyboard arrows). These
1259	    // dispatch a window event instead of phx-click="next_chapter" while
1260	    // the audio player is mounted so we can do a same-<audio>-element src
1261	    // swap instead of letting the server's push_patch leave us playing
1262	    // the previous chapter. When the next/prev chapter has no audio yet,
1263	    // goTo*Chapter returns false and we fall back to the server-owned
1264	    // path so the user can still navigate to audio-less chapters.
