1	/**
2	 * Autoplay regression: LV WebSocket disconnect during chapter boundary.
3	 *
4	 * Reproduces the mobile-screen-locked bug Noah hit in production:
5	 *
6	 *   - Listening on chapter N. Phone screen locks. The OS keeps the
7	 *     <audio> element playing via the Media Session, but the LV
8	 *     WebSocket is suspended/torn down.
9	 *   - Audio plays to the end of N. The hook's `ended` listener fires
10	 *     and JS-side swaps audio.src to chapter N+1 (using the prefetched
11	 *     blob). audio.play() succeeds — playback continues briefly into
12	 *     N+1 over the lock screen.
13	 *   - The hook ALSO calls `pushEvent("next_chapter")` so the server
14	 *     can push_patch the URL. With the socket dead, that event is
15	 *     dropped on the floor.
16	 *   - User wakes the phone. LV reconnects with a fresh process and
17	 *     re-mounts on the URL it sees, which is still chapter N. The
18	 *     audio element survives (phx-update="ignore") and audio.src is
19	 *     still chapter N+1's blob. State is now permanently inconsistent:
20	 *     URL says N, audio plays N+1, and the user has to refresh and
21	 *     manually navigate to N+1 to recover.
22	 *
23	 * Invariant this test pins: after `ended` + autoplay, however the LV
24	 * socket behaves around the chapter boundary, the URL must eventually
25	 * agree with the chapter audio.src points at. Either push_patch lands
26	 * (the desired fix), or audio.src reverts to match the URL — but the
27	 * two must NOT diverge permanently.
28	 */
29	import { describe, it, before, after } from "node:test";
30	import assert from "node:assert";
31	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
32	
33	describe("Audio autoplay across LV disconnect", () => {
34		let browser, page;
35	
36		before(async () => {
37			({ browser, page } = await setup());
38	
39			// Walk to the first chapter that has both audio AND a next-audio
40			// chapter (same precondition as audio-autoplay.test.js).
41			await openReader(page);
42			const chapters = await page.evaluate(() => {
43				const bar = document.getElementById("chapter-bar");
44				return bar ? JSON.parse(bar.dataset.chapters) : [];
45			});
46			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
47			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
48			assert.ok(chapters.length > 0, "fixture must seed ≥1 chapter");
49	
50			let found = false;
51			for (const ch of chapters) {
52				await page.goto(
53					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
54					{ waitUntil: "domcontentloaded" },
55				);
56				await page.waitForSelector("[data-phx-session].phx-connected", {
57					timeout: 10000,
58				});
59				await page.waitForSelector("#chapter-text", { timeout: 10000 });
60				const player = await page
61					.waitForSelector("#audio-player", { timeout: 1000 })
62					.catch(() => null);
63				if (player) {
64					const nextUrl = await page.$eval(
65						"#audio-player",
66						(el) => el.dataset.nextAudioUrl || "",
67					);
68					if (nextUrl) {
69						found = true;
70						break;
71					}
72				}
73			}
74			assert.ok(
75				found,
76				"fixture must seed ≥2 contiguous audio-ready chapters; check " +
77					"`audio_for` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
78			);
79	
80			// Enable autoplay and reload so the hook's PersistedRecord cache
81			// picks up the new value on its next mount.
82			await page.evaluate(() => {
83				const cur = (() => {
84					try {
85						return JSON.parse(
86							localStorage.getItem("readaloud-reader-settings") || "{}",
87						);
88					} catch {
