// Client-side durable buffer for audio-player diagnostic events.
//
// Same delivery architecture as progress_buffer (which owns reading
// *position*; this owns playback *diagnostics*): every event gets two
// paths to the server —
//   1. `pushEvent("player_events")` over the WS (immediate, optimistic)
//   2. `navigator.sendBeacon` to /api/books/:id/player-events, fired on
//      visibility transitions + pagehide
//
// The whole point of this channel is forensics for the sleeping-mobile
// autoplay bugs: when the screen locks, the WS suspends but the audio
// session (and this hook's event handlers) keep running. Events recorded
// while the socket is dead sit in localStorage and drain via beacon on the
// next visibility transition, or via WS replay on the next mount.
//
// Unlike progress observations, events are NOT idempotent server-side —
// a re-delivered event double-counts in Prometheus. We accept that: the
// prune window is short, the server treats counter rates as approximate,
// and every log line carries the client `at` timestamp so duplicates are
// trivially identifiable in Loki. Losing the last events before a phone
// slept would cost far more than a few duplicate counts.

import { beaconBestEffort, flushConfirmed } from "./confirmed_flush";
import type { PlayerEventDetailValue, PlayerEventPayload } from "./events";
import { isJsonObject, type JsonValue, parseJson } from "./types";

export interface PlayerEventBuffer {
  record(
    event: string,
    fields?: {
      readonly chapter_id?: string;
      readonly position_ms?: number;
      readonly detail?: Readonly<Record<string, PlayerEventDetailValue>>;
    },
  ): void;
  detach(): void;
}

interface PlayerEventBufferDeps {
  readonly bookId: number;
  readonly beaconUrl: string;
  readonly pushEvents: (events: ReadonlyArray<PlayerEventPayload>) => void;
}

const STORAGE_KEY_PREFIX = "readaloud-player-events:";
// Sized for the worst real-world gap this channel exists for: a phone
// playing prefetched audio through a commute-length dead zone. At ~2-4
// events/min while locked (heartbeats + transitions) that's roughly 30+
// minutes of forensics. The original 2-minute window self-destructed the
// evidence of the very incidents it was built to explain (2026-06-11:
// every event from the offline chapter was pruned before any flush
// could deliver it).
const MAX_BUFFER_ENTRIES = 300;
const BACKLOG_PRUNE_AGE_MS = 30 * 60_000;

function storageKey(bookId: number): string {
  return `${STORAGE_KEY_PREFIX}${bookId}`;
}

function isDetailValue(v: JsonValue | undefined): v is PlayerEventDetailValue {
  return (
    v === null ||
    typeof v === "string" ||
    typeof v === "number" ||
    typeof v === "boolean"
  );
}

function parseEvent(v: JsonValue): PlayerEventPayload | null {
  if (!isJsonObject(v)) return null;
  if (typeof v.event !== "string") return null;
  if (typeof v.at !== "string") return null;
  const out: {
    -readonly [K in keyof PlayerEventPayload]: PlayerEventPayload[K];
  } = { event: v.event, at: v.at };
  if (typeof v.chapter_id === "string") out.chapter_id = v.chapter_id;
  if (typeof v.position_ms === "number") out.position_ms = v.position_ms;
  if (v.detail !== undefined && isJsonObject(v.detail)) {
    const detail: Record<string, PlayerEventDetailValue> = {};
    for (const [key, value] of Object.entries(v.detail)) {
      if (isDetailValue(value)) detail[key] = value;
    }
    out.detail = detail;
  }
  return out;
}

function readBacklog(bookId: number): ReadonlyArray<PlayerEventPayload> {
  const raw = localStorage.getItem(storageKey(bookId));
  if (!raw) return [];
  try {
    const json = parseJson(raw);
    if (!Array.isArray(json)) return [];
    const out: PlayerEventPayload[] = [];
    for (const entry of json) {
      const event = parseEvent(entry);
      if (event) out.push(event);
    }
    return out;
  } catch {
    return [];
  }
}

function writeBacklog(
  bookId: number,
  backlog: ReadonlyArray<PlayerEventPayload>,
): void {
  if (backlog.length === 0) {
    localStorage.removeItem(storageKey(bookId));
    return;
  }
  localStorage.setItem(storageKey(bookId), JSON.stringify(backlog));
}

function pruneBacklog(
  backlog: ReadonlyArray<PlayerEventPayload>,
  now: number,
): ReadonlyArray<PlayerEventPayload> {
  const cutoff = now - BACKLOG_PRUNE_AGE_MS;
  const fresh = backlog.filter((entry) => {
    const ts = Date.parse(entry.at);
    return Number.isFinite(ts) && ts >= cutoff;
  });
  if (fresh.length <= MAX_BUFFER_ENTRIES) return fresh;
  return fresh.slice(-MAX_BUFFER_ENTRIES);
}

export function attachPlayerEventBuffer(
  deps: PlayerEventBufferDeps,
): PlayerEventBuffer {
  const { bookId, beaconUrl, pushEvents } = deps;

  // Replay anything still buffered from a prior mount or unload — this is
  // how events recorded while a locked phone's WS was dead reach the
  // server after the LV re-mounts on wake.
  const initial = pruneBacklog(readBacklog(bookId), Date.now());
  writeBacklog(bookId, initial);
  if (initial.length > 0) {
    try {
      pushEvents(initial);
    } catch {
      // pushEvent shouldn't throw; if it does, the beacon path still owns
      // durability on the next visibility transition.
    }
  }

  function append(event: PlayerEventPayload): void {
    const merged = pruneBacklog([...readBacklog(bookId), event], Date.now());
    writeBacklog(bookId, merged);
  }

  function flushViaBeacon(): void {
    const backlog = readBacklog(bookId);
    if (backlog.length === 0) return;
    if (typeof navigator === "undefined" || !navigator.sendBeacon) return;
    const body = new Blob([JSON.stringify({ events: backlog })], {
      type: "application/json",
    });
    if (navigator.sendBeacon(beaconUrl, body)) {
      writeBacklog(bookId, []);
    }
  }

  // Flush on BOTH visibility transitions: `hidden` is the canonical
  // last-chance moment, and `visible` drains anything recorded while the
  // screen was locked without waiting for the WS to re-establish.
  function onVisibilityChange(): void {
    flushViaBeacon();
  }

  document.addEventListener("visibilitychange", onVisibilityChange);
  window.addEventListener("pagehide", flushViaBeacon);

  return {
    record(event, fields) {
      const payload: PlayerEventPayload = {
        event,
        at: new Date().toISOString(),
        ...fields,
      };
      append(payload);
      try {
        pushEvents([payload]);
      } catch {
        // Same fallback rationale as the initial replay above.
      }
    },
    detach() {
      document.removeEventListener("visibilitychange", onVisibilityChange);
      window.removeEventListener("pagehide", flushViaBeacon);
    },
  };
}

// Client-side durable buffer for reading-progress observations.
//
// The reader's persistence boundary used to be LiveView-only: every
// `audio_position` push went straight to the WS, with no fallback if the
// socket was suspended. On mobile, locking the screen suspends the WS but
// not the native audio session — so audio kept advancing while every
// position observation was silently dropped, and PC resume landed at a
// stale chapter.
//
// This module fixes that by giving every observation two delivery paths:
//   1. `pushEvent` over the WS (immediate, optimistic)
//   2. `navigator.sendBeacon` to /api/books/:id/progress
//      (fired on visibilitychange:hidden + pagehide)
//
// Both transports converge on `ReadaloudReader.observe!/1`, which is
// idempotent under replay (stale-drop by `observed_at`). So sending the
// same observation twice is harmless. The buffer's job is to make sure
// every observation hits *at least one* of the two paths.
//
// Storage: a small bounded queue in localStorage keyed by bookId. Entries
// older than 60s are pruned on every observe — they're either already
// delivered (WS happy path) or no longer worth resending (server has
// fresher state from in-flight ticks).

import { type JsonValue, isJsonObject, parseJson } from "./types";

export interface ProgressObservation {
  readonly chapter_id: string;
  readonly audio_position_ms?: number;
  readonly scroll_position?: number;
  readonly observed_at: string;
  // Explicit chapter pivot (see ProgressObservationPayload in events.ts).
  // Must survive the localStorage round-trip: a buffered pivot replayed
  // after reconnect is exactly the case the server reconciler exists for.
  readonly pivot?: true;
}

export interface ProgressBuffer {
  observe(obs: Omit<ProgressObservation, "observed_at">): void;
  detach(): void;
}

interface ProgressBufferDeps {
  readonly bookId: number;
  readonly beaconUrl: string;
  readonly pushObservations: (
    observations: ReadonlyArray<ProgressObservation>,
  ) => void;
}

const STORAGE_KEY_PREFIX = "readaloud-progress-buffer:";
const MAX_BUFFER_ENTRIES = 50;
const BACKLOG_PRUNE_AGE_MS = 60_000;

function storageKey(bookId: number): string {
  return `${STORAGE_KEY_PREFIX}${bookId}`;
}

// --- Last-known-position cache ----------------------------------------
// The queue above is a delivery buffer: entries are cleared the moment a
// beacon is *queued* (not received). That's correct for delivery — the
// server's observe! is idempotent — but it means a page load right after
// a pagehide flush can race the beacon to the server and restore a stale
// position (the 2026-06-11 incident: beacon carrying 5.8s arrived 6s
// after the new page had already mounted at 0:00).
//
// This cache is the client's own memory of where playback last was:
// written on every observation, never cleared, read at player mount as a
// candidate alongside the server's initial position. Same-chapter only,
// recency-bounded — across devices or after a long gap the server row is
// the better authority.

export interface LastPosition {
  readonly chapter_id: string;
  readonly position_ms: number;
  readonly at_ms: number;
}

const LAST_POSITION_KEY_PREFIX = "readaloud-last-position:";

function lastPositionKey(bookId: number): string {
  return `${LAST_POSITION_KEY_PREFIX}${bookId}`;
}

export function writeLastPosition(
  bookId: number,
  chapterId: string,
  positionMs: number,
): void {
  const entry: LastPosition = {
    chapter_id: chapterId,
    position_ms: positionMs,
    at_ms: Date.now(),
  };
  try {
    localStorage.setItem(lastPositionKey(bookId), JSON.stringify(entry));
  } catch {
    // Quota/private-mode failures just mean no client-side restore.
  }
}

export function readLastPosition(bookId: number): LastPosition | null {
  const raw = localStorage.getItem(lastPositionKey(bookId));
  if (!raw) return null;
  try {
    const json = parseJson(raw);
    if (!isJsonObject(json)) return null;
    if (typeof json.chapter_id !== "string") return null;
    if (typeof json.position_ms !== "number") return null;
    if (typeof json.at_ms !== "number") return null;
    return {
      chapter_id: json.chapter_id,
      position_ms: json.position_ms,
      at_ms: json.at_ms,
    };
  } catch {
    return null;
  }
}

function parseObservation(v: JsonValue): ProgressObservation | null {
  if (!isJsonObject(v)) return null;
  if (typeof v.chapter_id !== "string") return null;
  if (typeof v.observed_at !== "string") return null;
  const out: {
    -readonly [K in keyof ProgressObservation]: ProgressObservation[K];
  } = {
    chapter_id: v.chapter_id,
    observed_at: v.observed_at,
  };
  if (typeof v.audio_position_ms === "number") {
    out.audio_position_ms = v.audio_position_ms;
  }
  if (typeof v.scroll_position === "number") {
    out.scroll_position = v.scroll_position;
  }
  if (v.pivot === true) {
    out.pivot = true;
  }
  return out;
}

function readBacklog(bookId: number): ReadonlyArray<ProgressObservation> {
  const raw = localStorage.getItem(storageKey(bookId));
  if (!raw) return [];
  try {
    const json = parseJson(raw);
    if (!Array.isArray(json)) return [];
    const out: ProgressObservation[] = [];
    for (const entry of json) {
      const obs = parseObservation(entry);
      if (obs) out.push(obs);
    }
    return out;
  } catch {
    return [];
  }
}

function writeBacklog(
  bookId: number,
  backlog: ReadonlyArray<ProgressObservation>,
): void {
  if (backlog.length === 0) {
    localStorage.removeItem(storageKey(bookId));
    return;
  }
  localStorage.setItem(storageKey(bookId), JSON.stringify(backlog));
}

function pruneBacklog(
  backlog: ReadonlyArray<ProgressObservation>,
  now: number,
): ReadonlyArray<ProgressObservation> {
  const cutoff = now - BACKLOG_PRUNE_AGE_MS;
  const fresh = backlog.filter((entry) => {
    const ts = Date.parse(entry.observed_at);
    return Number.isFinite(ts) && ts >= cutoff;
  });
  if (fresh.length <= MAX_BUFFER_ENTRIES) return fresh;
  // Keep the most recent MAX_BUFFER_ENTRIES — observed_at is monotonic
  // for fresh inserts, so the tail is what we want.
  return fresh.slice(-MAX_BUFFER_ENTRIES);
}

export function attachProgressBuffer(deps: ProgressBufferDeps): ProgressBuffer {
  const { bookId, beaconUrl, pushObservations } = deps;

  // Replay anything still in localStorage from a prior mount or unload.
  // Prune first — if the user force-killed the tab N days ago, the same
  // stale entry would otherwise re-fire on every mount forever (server
  // stale-drops it, but that's bytes wasted on every page load). Persist
  // the pruned form back so the cleanup survives even if no observation
  // happens this mount.
  const initial = pruneBacklog(readBacklog(bookId), Date.now());
  writeBacklog(bookId, initial);
  if (initial.length > 0) {
    try {
      pushObservations(initial);
    } catch {
      // pushEvent shouldn't throw; if it does, sendBeacon still owns the
      // durable path and we fall back on next visibilitychange.
    }
  }

  function append(obs: ProgressObservation): void {
    const now = Date.now();
    const merged = pruneBacklog([...readBacklog(bookId), obs], now);
    writeBacklog(bookId, merged);
  }

  function flushViaBeacon(): void {
    const backlog = readBacklog(bookId);
    if (backlog.length === 0) return;
    if (typeof navigator === "undefined" || !navigator.sendBeacon) return;
    const body = new Blob([JSON.stringify({ observations: backlog })], {
      type: "application/json",
    });
    const accepted = navigator.sendBeacon(beaconUrl, body);
    if (accepted) {
      // sendBeacon's "accepted" only means the browser queued the request,
      // not that the server received it. But the request has the same
      // observation payload the server's idempotent `observe!/1` already
      // tolerates as a duplicate, so clearing locally is safe — even if
      // the beacon fails, the next observe will re-seed the buffer.
      writeBacklog(bookId, []);
    }
  }

  function onVisibilityHidden(): void {
    if (document.visibilityState === "hidden") flushViaBeacon();
  }

  // pagehide is more reliable than visibilitychange on iOS Safari for
  // tab close + bfcache eviction. Both are registered; flushViaBeacon is
  // idempotent on an empty backlog.
  document.addEventListener("visibilitychange", onVisibilityHidden);
  window.addEventListener("pagehide", flushViaBeacon);

  return {
    observe(input) {
      const obs: ProgressObservation = {
        ...input,
        observed_at: new Date().toISOString(),
      };
      if (typeof obs.audio_position_ms === "number") {
        writeLastPosition(bookId, obs.chapter_id, obs.audio_position_ms);
      }
      append(obs);
      try {
        pushObservations([obs]);
      } catch {
        // Same fallback rationale as the initial replay above.
      }
    },
    detach() {
      document.removeEventListener("visibilitychange", onVisibilityHidden);
      window.removeEventListener("pagehide", flushViaBeacon);
    },
  };
}

