1	/**
2	 * Audio auto-next-chapter test.
3	 *
4	 * Verifies the chapter swap on `ended` keeps the same <audio> element and
5	 * uses LiveView push_patch (no full navigation). This is the critical
6	 * mobile-lock-screen fix: a full navigation tears down the OS audio
7	 * session, which is why autoplay used to fail when the phone was asleep.
8	 *
9	 * Requires the canonical e2e fixture: a chapter with audio that *also*
10	 * has a next chapter with audio (so `next_audio_url` is populated).
11	 * `seed_e2e_book!/1` defaults to `audio_for: [1, 2]` — chapter 1 sees
12	 * chapter 2 as the next audio-ready chapter.
13	 */
14	import { describe, it, before, after } from "node:test";
15	import assert from "node:assert";
16	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
17	
18	describe("Audio auto-next-chapter", () => {
19		let browser, page;
20	
21		before(async () => {
22			({ browser, page } = await setup());
23	
24			// Find a chapter that has audio AND a next-chapter audio URL.
25			// The fixture guarantees chapter 1 satisfies this; we still walk
26			// the bar in case the test ordering shifted.
27			await openReader(page);
28			const chapters = await page.evaluate(() => {
29				const bar = document.getElementById("chapter-bar");
30				return bar ? JSON.parse(bar.dataset.chapters) : [];
31			});
32	
33			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
34			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
35			assert.ok(
36				chapters.length > 0,
37				"fixture must seed ≥1 chapter; check ReadaloudAudiobook.Fixtures.E2E.seed!/1",
38			);
39	
40			let found = false;
41			for (const ch of chapters) {
42				await page.goto(
43					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
44					{ waitUntil: "domcontentloaded" },
45				);
46				await page.waitForSelector("[data-phx-session].phx-connected", {
47					timeout: 10000,
48				});
49				await page.waitForSelector("#chapter-text", { timeout: 10000 });
50				// `#audio-player` is gated by audio_state == :ready; absence after
51				// chapter-text renders means this chapter has no audio. Don't fail —
52				// just walk to the next chapter.
53				const player = await page
54					.waitForSelector("#audio-player", { timeout: 1000 })
55					.catch(() => null);
56				if (player) {
57					const nextUrl = await page.$eval(
58						"#audio-player",
59						(el) => el.dataset.nextAudioUrl || "",
60					);
61					if (nextUrl) {
62						found = true;
63						break;
64					}
65				}
66			}
67			assert.ok(
68				found,
69				"fixture must seed ≥2 contiguous audio-ready chapters; the audio-* " +
70					"tests need both a current chapter and a next chapter with audio. " +
71					"Check `audio_for` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
72			);
73		});
74	
75		after(async () => {
76			await teardown(browser);
77		});
78	
79		it("player exposes next-chapter data attrs", async () => {
80			const attrs = await page.$eval("#audio-player", (el) => ({
81				audioUrl: el.dataset.audioUrl,
82				nextAudioUrl: el.dataset.nextAudioUrl,
83				nextTimingsUrl: el.dataset.nextTimingsUrl,
84				nextChapterId: el.dataset.nextChapterId,
85				chapterId: el.dataset.chapterId,
86				bookTitle: el.dataset.bookTitle,
87				chapterTitle: el.dataset.chapterTitle,
88			}));
89			assert.ok(attrs.audioUrl, "audioUrl must be set");
90			assert.ok(attrs.nextAudioUrl, "nextAudioUrl must be set");
91			assert.ok(attrs.nextTimingsUrl, "nextTimingsUrl must be set");
92			assert.ok(attrs.nextChapterId, "nextChapterId must be set");
93			assert.notStrictEqual(
94				attrs.audioUrl,
95				attrs.nextAudioUrl,
96				"next URL must differ from current",
97			);
98			assert.ok(attrs.bookTitle, "bookTitle must be set for Media Session");
99			assert.ok(attrs.chapterTitle, "chapterTitle must be set for Media Session");
100		});
101	
102		it("Media Session metadata is registered", async (t) => {
103			// Wait for the hook to populate MediaMetadata (or for the browser
104			// to declare it doesn't support MediaSession at all).
105			await page
106				.waitForFunction(
107					() =>
108						!("mediaSession" in navigator) ||
109						navigator.mediaSession.metadata !== null,
110					{ timeout: 5000 },
111				)
112				.catch(() => {});
113			const meta = await page.evaluate(() => {
114				if (!("mediaSession" in navigator)) return null;
115				const m = navigator.mediaSession.metadata;
116				if (!m) return null;
117				return { title: m.title, artist: m.artist, album: m.album };
118			});
119			// MediaSession is a runtime browser capability, not a fixture
120			// precondition — soft-skip if the headless chromium build lacks it.
121			if (meta === null) {
122				t.skip("MediaSession not available in this browser");
123				return;
124			}
125			assert.ok(meta.title?.length > 0, "Media Session title should be set");
126			assert.ok(meta.artist?.length > 0, "Media Session artist should be set");
127		});
128	
129		it("prefetches next chapter audio into a Blob URL while current plays", async () => {
130			// Enable autoNextChapter (gates prefetch) and reload so the
131			// PersistedRecord cache picks it up.
132			await page.evaluate(() => {
133				const cur = (() => {
134					try {
135						return JSON.parse(
136							localStorage.getItem("readaloud-reader-settings") || "{}",
137						);
138					} catch {
139						return {};
140					}
141				})();
142				cur.autoNextChapter = true;
143				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
144			});
145			await page.reload({ waitUntil: "domcontentloaded" });
146			await page.waitForSelector("#audio-element", { timeout: 10000 });
147	
148			// Drive currentTime past the 15% prefetch trigger fraction by
149			// poking the audio element directly. We're not asserting playback,
150			// just want a `timeupdate` to fire with currentTime/duration > 0.15.
151			// Wait for metadata first so duration is known.
152			await page.evaluate(
153				() =>
154					new Promise((resolve) => {
155						const a = document.getElementById("audio-element");
156						if (!a) return resolve();
157						if (a.readyState >= 1 && Number.isFinite(a.duration))
158							return resolve();
159						a.addEventListener("loadedmetadata", () => resolve(), { once: true });
160					}),
161			);
162			await page.evaluate(() => {
163				const a = document.getElementById("audio-element");
164				if (!a || !Number.isFinite(a.duration)) return;
165				a.currentTime = a.duration * 0.2;
166				a.dispatchEvent(new Event("timeupdate"));
167			});
168	
169			// Wait for the fetch to fire. fetch() shows up as a `resource`
170			// performance entry; we can't reach into the hook's closure, but
171			// we *can* observe the request itself.
172			const nextUrl = await page.$eval(
173				"#audio-player",
174				(el) => el.dataset.nextAudioUrl || "",
175			);
176			await page
177				.waitForFunction(
178					() =>
179						performance
180							.getEntriesByType("resource")
181							.some(
182								(e) =>
183									e.name.includes("/api/books/") &&
184									e.name.includes("/audio") &&
185									e.initiatorType === "fetch",
186							),
187					{ timeout: 20000 },
188				)
189				.catch(() => {
190					throw new Error(
191						`expected a fetch() to ${nextUrl} after currentTime crossed 15%, ` +
192							"but none was observed within 20s",
193					);
194				});
195		});
196	
197		it("ended event swaps audio.src + patches URL without tearing down player", async () => {
198			// Snapshot current state.
199			const before = await page.evaluate(() => {
200				const player = document.getElementById("audio-player");
201				const audio = document.getElementById("audio-element");
202				return {
203					url: window.location.pathname + window.location.search,
204					audioSrc: audio?.src ?? null,
205					nextAudioUrl: player?.dataset.nextAudioUrl ?? null,
206					nextChapterId: player?.dataset.nextChapterId ?? null,
207					audioNodeId: audio ? audio.dataset.testId : null,
208				};
209			});
210	
211			assert.ok(before.nextAudioUrl, "must have a next audio URL to swap to");
212			assert.ok(
213				before.audioSrc?.includes(
214					`/chapters/${before.url.match(/\/read\/(\d+)/)?.[1]}/audio`,
215				),
216				`audio src should be the current chapter's URL, got ${before.audioSrc}`,
217			);
218	
219			// Auto-next-chapter is a user-controlled reader setting persisted in
220			// localStorage. The hook reads it via PersistedRecord, which caches
221			// the value at module-load time — so we must set localStorage *and
222			// reload* for the new value to be picked up.
223			await page.evaluate(() => {
224				const cur = (() => {
225					try {
226						return JSON.parse(
227							localStorage.getItem("readaloud-reader-settings") || "{}",
228						);
229					} catch {
230						return {};
231					}
232				})();
233				cur.autoNextChapter = true;
234				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
235			});
236			await page.reload({ waitUntil: "domcontentloaded" });
237			await page.waitForSelector("#audio-element", { timeout: 10000 });
238			// Wait for the hook to finish mount + apply the fresh
239			// PersistedRecord — observable as audio.src being populated.
240			await page.waitForFunction(
241				() => {
242					const a = document.getElementById("audio-element");
243					return a && a.src && a.src.length > 0;
244				},
245				{ timeout: 5000 },
246			);
247	
248			// Mark the (post-reload) audio element so we can prove identity
249			// after the swap. Use a JS expando property (not a DOM attribute)
250			// because morphdom strips attributes not declared in the server
251			// template — even on phx-update="ignore" elements (it preserves
252			// children, not custom attrs).
253			await page.evaluate(() => {
254				const a = document.getElementById("audio-element");
255				if (a) a.__readaloudTestMarker = "same-node-marker";
256			});
257	
258			// Trigger the `ended` event on the audio element. The hook listens
259			// for this and is supposed to swap src to the next chapter and push
260			// next_chapter to the server (push_patch).
261			await page.evaluate(() => {
262				const a = document.getElementById("audio-element");
263				if (a) a.dispatchEvent(new Event("ended"));
264			});
265	
266			// Wait for the JS swap + LV push_patch round-trip — both observable.
267			// The URL changes via push_patch; the audio.src changes via the
268			// hook's ended handler.
269			await page.waitForFunction(
270				(targetChapterId) => {
271					const url = window.location.pathname + window.location.search;
272					const a = document.getElementById("audio-element");
273					const urlChanged = url.includes(`/read/${targetChapterId}`);
274					const srcChanged = a?.src && !a.src.includes(`/chapters/1/audio`);
275					return urlChanged && srcChanged;
276				},
277				{ timeout: 5000 },
278				before.nextChapterId,
279			);
280	
281			const after = await page.evaluate(() => {
282				const audio = document.getElementById("audio-element");
283				return {
284					url: window.location.pathname + window.location.search,
285					audioSrc: audio?.src ?? null,
286					audioNodeMarker: audio ? audio.__readaloudTestMarker : null,
287				};
288			});
289	
290			// Same DOM node — proves push_patch (not push_navigate).
291			assert.strictEqual(
292				after.audioNodeMarker,
293				"same-node-marker",
294				"audio element must be the SAME node — push_navigate would replace it",
295			);
296	
297			// audio.src now points at the next chapter — either as the network
298			// URL or as a `blob:` URL when the prefetch beat us to it. The
299			// blob path is the one that actually fixes sleeping-mobile
300			// autoplay, so when it's chosen we just verify the prefix.
301			const expectedNetworkUrl =
302				before.nextAudioUrl && new URL(before.nextAudioUrl, BASE_URL).toString();
303			const isBlob = after.audioSrc?.startsWith("blob:");
304			if (isBlob) {
305				assert.ok(
306					after.audioSrc?.startsWith(`blob:${BASE_URL}`),
307					`expected a blob: URL on the page origin, got ${after.audioSrc}`,
308				);
309			} else {
310				assert.strictEqual(
311					after.audioSrc,
312					expectedNetworkUrl,
313					`audio.src should be next chapter URL after ended, got ${after.audioSrc}`,
314				);
315			}
316	
317			// URL got patched to the next chapter.
318			assert.ok(
319				after.url.includes(`/read/${before.nextChapterId}`),
320				`URL should be patched to /read/${before.nextChapterId}, got ${after.url}`,
321			);
322		});
323	});
