1	/**
2	 * Autoplay regression: LV WebSocket disconnect during chapter boundary.
3	 *
4	 * Reproduces the mobile-screen-locked bug Noah hit in production:
5	 *
6	 *   - Listening on chapter N. Phone screen locks. The OS keeps the
7	 *     <audio> element playing via the Media Session, but the LV
8	 *     WebSocket is suspended/torn down.
9	 *   - Audio plays to the end of N. The hook's `ended` listener fires
10	 *     and JS-side swaps audio.src to chapter N+1 (using the prefetched
11	 *     blob). audio.play() succeeds — playback continues briefly into
12	 *     N+1 over the lock screen.
13	 *   - The hook ALSO calls `pushEvent("next_chapter")` so the server
14	 *     can push_patch the URL. With the socket dead, that event is
15	 *     dropped on the floor.
16	 *   - User wakes the phone. LV reconnects with a fresh process and
17	 *     re-mounts on the URL it sees, which is still chapter N. The
18	 *     audio element survives (phx-update="ignore") and audio.src is
19	 *     still chapter N+1's blob. State is now permanently inconsistent:
20	 *     URL says N, audio plays N+1, and the user has to refresh and
21	 *     manually navigate to N+1 to recover.
22	 *
23	 * Invariant this test pins: after `ended` + autoplay, however the LV
24	 * socket behaves around the chapter boundary, the URL must eventually
25	 * agree with the chapter audio.src points at. Either push_patch lands
26	 * (the desired fix), or audio.src reverts to match the URL — but the
27	 * two must NOT diverge permanently.
28	 */
29	import { describe, it, before, after } from "node:test";
30	import assert from "node:assert";
31	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
32	
33	describe("Audio autoplay across LV disconnect", () => {
34		let browser, page;
35	
36		before(async () => {
37			({ browser, page } = await setup());
38	
39			// Walk to the first chapter that has both audio AND a next-audio
40			// chapter (same precondition as audio-autoplay.test.js).
41			await openReader(page);
42			const chapters = await page.evaluate(() => {
43				const bar = document.getElementById("chapter-bar");
44				return bar ? JSON.parse(bar.dataset.chapters) : [];
45			});
46			const bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
47			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
48			assert.ok(chapters.length > 0, "fixture must seed ≥1 chapter");
49	
50			let found = false;
51			for (const ch of chapters) {
52				await page.goto(
53					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
54					{ waitUntil: "domcontentloaded" },
55				);
56				await page.waitForSelector("[data-phx-session].phx-connected", {
57					timeout: 10000,
58				});
59				await page.waitForSelector("#chapter-text", { timeout: 10000 });
60				const player = await page
61					.waitForSelector("#audio-player", { timeout: 1000 })
62					.catch(() => null);
63				if (player) {
64					const nextUrl = await page.$eval(
65						"#audio-player",
66						(el) => el.dataset.nextAudioUrl || "",
67					);
68					if (nextUrl) {
69						found = true;
70						break;
71					}
72				}
73			}
74			assert.ok(
75				found,
76				"fixture must seed ≥2 contiguous audio-ready chapters; check " +
77					"`audio_for` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
78			);
79	
80			// Enable autoplay and reload so the hook's PersistedRecord cache
81			// picks up the new value on its next mount.
82			await page.evaluate(() => {
83				const cur = (() => {
84					try {
85						return JSON.parse(
86							localStorage.getItem("readaloud-reader-settings") || "{}",
87						);
88					} catch {
89						return {};
90					}
91				})();
92				cur.autoNextChapter = true;
93				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
94			});
95			await page.reload({ waitUntil: "domcontentloaded" });
96			await page.waitForSelector("#audio-element", { timeout: 10000 });
97			// Wait for the hook to apply its initial src so we have something
98			// to swap away from.
99			await page.waitForFunction(
100				() => {
101					const a = document.getElementById("audio-element");
102					return a?.src && a.src.includes("/api/books/");
103				},
104				{ timeout: 5000 },
105			);
106		});
107	
108		after(async () => {
109			await teardown(browser);
110		});
111	
112		it("browser URL updates to next chapter immediately, even with the LV socket dead", async () => {
113			// This is the invariant we want from the fix: the URL must change
114			// client-side as part of the swap, not contingent on a server
115			// roundtrip. The original code only updates the URL via
116			// `push_patch` (server-side), which means a screen-locked phone
117			// whose LV diff doesn't make it back to the browser leaves the
118			// URL pinned at the previous chapter while audio plays the next
119			// one — exactly the user-visible bug from prod logs.
120			//
121			// We test the invariant directly by killing the socket and NOT
122			// reconnecting it. If the URL only updates via `push_patch`, this
123			// test fails. If the swap also updates the URL via History API
124			// (or LV's own JS-side patch), it passes regardless of socket
125			// state.
126	
127			const before = await page.evaluate(() => {
128				const player = document.getElementById("audio-player");
129				return {
130					url: window.location.pathname,
131					chapterId: player?.dataset.chapterId,
132					nextChapterId: player?.dataset.nextChapterId,
133				};
134			});
135			assert.ok(before.nextChapterId, "must have a next chapter to swap to");
136			assert.notStrictEqual(
137				before.chapterId,
138				before.nextChapterId,
139				"sanity: next chapter id must differ from current",
140			);
141	
142			// Kill the LV socket and disable reconnect so any pushEvent the
143			// hook fires goes nowhere — like a phone whose WebSocket is
144			// suspended and whose server-side LV process eventually times out.
145			// Phoenix's Channel buffers events while the socket is briefly
146			// down and flushes on rejoin; the user-visible bug is the case
147			// where the socket *doesn't* come back in time and the buffered
148			// event is lost. We model that here as "no reconnect at all."
149			await page.evaluate(() => {
150				// `liveSocket.disconnect()` closes the socket; without
151				// `connect()` it stays closed. We also override `connect()`
152				// to a no-op so any internal Phoenix reconnect logic can't
153				// silently bring it back during the test window.
154				window.liveSocket.disconnect();
155				window.liveSocket.connect = () => {};
156			});
