1	/**
2	 * Shared helpers for E2E tests.
3	 *
4	 * Canonical entry point: `mix test.e2e`, which boots the readaloud
5	 * release in a NixOS VM, seeds the fixture book via
6	 * `ReadaloudAudiobook.Fixtures.E2E.seed!/1`, and runs this suite
7	 * against http://localhost:4000 with BOOK_ID=1.
8	 *
9	 * Configurable via env vars (override when running outside the VM):
10	 *   BASE_URL  - server URL (default: http://localhost:4000)
11	 *   HEADLESS  - "false" to show the browser (default: true)
12	 *   BOOK_ID   - book ID to test with (default: 1)
13	 */
14	import puppeteer from "puppeteer";
15	
16	export const BASE_URL = process.env.BASE_URL || "http://localhost:4000";
17	export const BOOK_ID = process.env.BOOK_ID || "1";
18	export const HEADLESS = process.env.HEADLESS !== "false";
19	
20	/**
21	 * Launch browser + page with sensible defaults.
22	 *
23	 * When BROWSER_WS_ENDPOINT is set (the VM runs browser-server.js once
24	 * for the whole suite), connect to the shared Chromium and return an
25	 * isolated incognito context instead of launching a fresh browser —
26	 * BrowserContext and Browser expose the same newPage()/close() surface,
27	 * so callers and teardown() don't care which they got.
28	 */
29	export async function setup() {
30		const wsEndpoint = process.env.BROWSER_WS_ENDPOINT;
31		let browser;
32		if (wsEndpoint) {
33			const shared = await puppeteer.connect({ browserWSEndpoint: wsEndpoint });
34			browser = await shared.createBrowserContext();
35		} else {
36			browser = await puppeteer.launch({
37				headless: HEADLESS,
38				args: ["--no-sandbox", "--disable-setuid-sandbox"],
39			});
40		}
41		const page = await browser.newPage();
42		await page.setViewport({ width: 1280, height: 800 });
43		return { browser, page };
44	}
45	
46	/** Close the browser (or the per-file context of the shared browser). */
47	export async function teardown(browser) {
48		if (typeof browser.browser === "function") {
49			// Shared-browser mode: `browser` is a per-file BrowserContext.
50			// Close it, then disconnect this process's CDP connection — the
51			// open websocket otherwise keeps the node:test child process
52			// alive forever and the suite hangs after the first file.
53			const shared = browser.browser();
54			await browser.close();
55			await shared.disconnect();
56		} else {
57			await browser.close();
58		}
59	}
60	
61	/**
62	 * Navigate to a reader chapter page and wait for LiveView to mount AND
63	 * connect its socket.
64	 *
65	 * Waits for three signals in order:
66	 *   1. domcontentloaded — initial (dead-render) HTML parsed
67	 *   2. [data-phx-session].phx-connected — LiveView socket joined
68	 *   3. #chapter-text — chapter content present in the DOM
69	 *
70	 * (2) is the load-bearing one: [data-phx-session] and #chapter-text
71	 * both exist in the dead render, but phx-click/pushEvent interactions
72	 * race the socket join without it. domcontentloaded + .phx-connected is
73	 * both faster (no 500ms networkidle heuristic per navigation) and a
74	 * stronger guarantee than the old networkidle2 wait. Tests that need a
75	 * specific element (e.g. #audio-player when audio_state is :ready)
76	 * should still `waitForSelector` it explicitly — openReader only
77	 * guarantees the chapter has rendered and the LV is live.
78	 */
79	export async function openReader(page, { bookId, chapterId } = {}) {
80		const bid = bookId || BOOK_ID;
81		// If no chapterId given, go to the book page first and grab the first chapter link
82		if (!chapterId) {
83			await page.goto(`${BASE_URL}/books/${bid}`, {
84				waitUntil: "domcontentloaded",
85			});
86			// Find the first "Read" link that points to /books/:id/read/:chapter_id
87			const href = await page.evaluate((id) => {
88				const link = document.querySelector(`a[href*="/books/${id}/read/"]`);
89				return link ? link.getAttribute("href") : null;
90			}, bid);
91			if (!href) throw new Error(`No chapter link found for book ${bid}`);
92			chapterId = href.match(/\/read\/(\d+)/)?.[1];
93		}
94		const url = `${BASE_URL}/books/${bid}/read/${chapterId}?nav=internal`;
95		await page.goto(url, { waitUntil: "domcontentloaded" });
96		await page.waitForSelector("[data-phx-session].phx-connected", {
97			timeout: 10000,
98		});
99		await page.waitForSelector("#chapter-text", { timeout: 10000 });
100		return { bookId: bid, chapterId };
101	}
102	
103	/** Trigger the floating pill to show (mouse move on desktop). */
104	export async function showPill(page) {
105		await page.mouse.move(640, 400);
106		await page.mouse.move(641, 401);
107		// Wait for opacity transition
108		await page.waitForSelector("#floating-pill.opacity-100", { timeout: 5000 });
109	}
110	
111	/** Open the settings popover via the gear button. */
112	export async function openSettings(page) {
113		await showPill(page);
114		// `#floating-pill button[phx-click]` would match prev/next/gear and
115		// hit the first one in DOM order (prev). Walk the buttons explicitly
116		// and click the one that contains a hero-cog icon span — robust
117		// across :has()-support quirks and DOM ordering changes.
118		const gearHandle = await page.evaluateHandle(() => {
119			const pill = document.getElementById("floating-pill");
120			if (!pill) return null;
121			for (const btn of pill.querySelectorAll("button")) {
122				if (btn.querySelector('[class*="hero-cog"]')) return btn;
123			}
124			return null;
125		});
126		const isElement = await gearHandle.evaluate((el) => el !== null);
127		if (!isElement) {
128			throw new Error("openSettings: gear button (hero-cog) not found in pill");
129		}
130		// Already open? `JS.toggle` would close it. Skip the click in that
131		// case — tests call openSettings repeatedly across describe blocks.
132		const alreadyOpen = await page.evaluate(() => {
133			const el = document.getElementById("reader-settings");
134			return el ? getComputedStyle(el).display !== "none" : false;
135		});
136		if (alreadyOpen) return;
137		// Click via puppeteer's API so we get a real CDP click event that
138		// Phoenix LV's phx-click handler responds to (synthetic `el.click()`
139		// can race the LV command pipeline).
140		await gearHandle.click();
141		// `JS.toggle` flips the inline `display` style — it does NOT remove
142		// the Tailwind `hidden` class (Tailwind's `display: none` is overridden
143		// by the inline `display: block`, so `:not(.hidden)` would never match).
144		// Wait on the actual visibility instead.
145		await page.waitForFunction(
146			() => {
147				const el = document.getElementById("reader-settings");
148				return el && getComputedStyle(el).display !== "none";
149			},
150			{ timeout: 3000 },
151		);
152	}
153	
154	/** Get all chapter IDs for a book by reading the chapter bar data attribute. */
155	export async function getChapters(page) {
156		return page.evaluate(() => {
157			const bar = document.getElementById("chapter-bar");
158			if (!bar) return [];
159			return JSON.parse(bar.dataset.chapters);
160		});
161	}
