1	/**
2	 * Autoplay chain across TWO offline chapter boundaries + recovery.
3	 *
4	 * audio-autoplay-disconnect.test.js pins the FIRST boundary: with the LV
5	 * socket dead, `ended` still swaps audio.src and pushState's the URL.
6	 * This file pins what the 2026-06-11 commute incident showed happens at
7	 * the SECOND boundary:
8	 *
9	 *   - Chapter N ends offline; the hook swaps to N+1's prefetched blob.
10	 *     The server never delivers a dataset refresh (WS is dead), so the
11	 *     dataset still describes chapter N — whose "next" is N+1.
12	 *   - Chapter N+1 ends. Pre-fix, the hook read its nav target from the
13	 *     stale dataset and "advanced" to N+1 — the chapter that just
14	 *     finished — restarting it at 0:00 over a network URL with no
15	 *     network (NETWORK_NO_SOURCE) and clobbering the position cache.
16	 *   - The network came back 16s later, but nothing ever looked at the
17	 *     paused element again. Playback stayed dead for the rest of the
18	 *     commute.
19	 *
20	 * The fix: the prefetch bundle also fetches /nav for the next chapter,
21	 * so by the time N+1 plays, its own neighbors are client-local
22	 * (CHAPTER_WINDOW). A self-swap guard refuses targets equal to the
23	 * loaded chapter, and a pending-autoplay intent retries the failed swap
24	 * when connectivity returns.
25	 *
26	 * Requires the canonical fixture's three consecutive audio-ready
27	 * chapters (`audio_for: [1, 2, 3]`).
28	 */
29	import { describe, it, before, after } from "node:test";
30	import assert from "node:assert";
31	import { setup, teardown, openReader, BASE_URL } from "../helpers.js";
32	
33	describe("Autoplay across two offline chapter boundaries", () => {
34		let browser, page;
35		/** Every console line the page emits; the hook's log() mirrors all
36		 * player events to console.log("[autoplay <ts>] <event>", {...}). */
37		const consoleLines = [];
38		const sawLog = (event) =>
39			consoleLines.some((line) => line.includes(`] ${event}`));
40		const waitForLog = async (event, timeoutMs = 5000) => {
41			const deadline = Date.now() + timeoutMs;
42			while (Date.now() < deadline) {
43				if (sawLog(event)) return;
44				await new Promise((r) => setTimeout(r, 100));
45			}
46			throw new Error(
47				`expected console log event "${event}" within ${timeoutMs}ms`,
48			);
49		};
50	
51		let bookId;
52		let ch1, ch2, ch3; // chapter ids (strings), all audio-ready
53	
54		before(async () => {
55			({ browser, page } = await setup());
56			page.on("console", (msg) => consoleLines.push(msg.text()));
57	
58			// Walk to a chapter with audio AND a next-audio chapter (same
59			// precondition walk as audio-autoplay.test.js).
60			await openReader(page);
61			const chapters = await page.evaluate(() => {
62				const bar = document.getElementById("chapter-bar");
63				return bar ? JSON.parse(bar.dataset.chapters) : [];
64			});
65			bookId = page.url().match(/\/books\/(\d+)\/read/)?.[1];
66			assert.ok(bookId, "openReader must land on a /books/:id/read/:cid URL");
67			assert.ok(chapters.length >= 3, "fixture must seed ≥3 chapters");
68	
69			for (const ch of chapters) {
70				await page.goto(
71					`${BASE_URL}/books/${bookId}/read/${ch.id}?nav=internal`,
72					{ waitUntil: "domcontentloaded" },
73				);
74				await page.waitForSelector("[data-phx-session].phx-connected", {
75					timeout: 10000,
76				});
77				await page.waitForSelector("#chapter-text", { timeout: 10000 });
78				const player = await page
79					.waitForSelector("#audio-player", { timeout: 1000 })
80					.catch(() => null);
81				if (player) {
82					const next = await page.$eval("#audio-player", (el) => ({
83						nextAudioUrl: el.dataset.nextAudioUrl || "",
84						nextChapterId: el.dataset.nextChapterId || "",
85					}));
86					if (next.nextAudioUrl) {
87						ch1 = String(ch.id);
88						ch2 = next.nextChapterId;
89						break;
90					}
91				}
92			}
93			assert.ok(
94				ch1 && ch2,
95				"fixture must seed ≥2 contiguous audio-ready chapters; check " +
96					"`audio_for` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
97			);
98	
99			// The second boundary needs a THIRD consecutive audio-ready chapter.
100			// Read it from the /nav endpoint — which is also the data source the
101			// hook's prefetch bundle uses, so this doubles as an endpoint check.
102			const nav = await page.evaluate(async (url) => {
103				const r = await fetch(url);
104				return r.ok ? r.json() : null;
105			}, `${BASE_URL}/api/books/${bookId}/chapters/${ch2}/nav`);
106			assert.ok(
107				nav?.next?.audio_url,
108				`chapter ${ch2} must have an audio-ready next chapter; check ` +
109					"`audio_for: [1, 2, 3]` in ReadaloudAudiobook.Fixtures.E2E.seed!/1.",
110			);
111			ch3 = String(nav.next.chapter_id);
112	
113			// Enable auto-next-chapter and reload so the hook's PersistedRecord
114			// cache picks it up, then wait for the initial src.
115			await page.goto(`${BASE_URL}/books/${bookId}/read/${ch1}?nav=internal`, {
116				waitUntil: "domcontentloaded",
117			});
118			await page.evaluate(() => {
119				const cur = (() => {
120					try {
121						return JSON.parse(
122							localStorage.getItem("readaloud-reader-settings") || "{}",
123						);
124					} catch {
125						return {};
126					}
127				})();
128				cur.autoNextChapter = true;
129				localStorage.setItem("readaloud-reader-settings", JSON.stringify(cur));
130			});
131			await page.reload({ waitUntil: "domcontentloaded" });
132			await page.waitForSelector("#audio-element", { timeout: 10000 });
133			await page.waitForFunction(
134				() => {
135					const a = document.getElementById("audio-element");
136					return a?.src?.includes("/api/books/");
137				},
138				{ timeout: 5000 },
139			);
140		});
141	
142		after(async () => {
143			await teardown(browser);
144		});
145	
146		it("second `ended` offline advances to chapter 3 via the prefetched nav window (no self-swap)", async () => {
147			// Arm the prefetch bundle while the network still works: cross the
148			// 15% trigger fraction and wait for BOTH the audio blob and the
149			// /nav neighbors to land. This is the on-line half of the contract
150			// — everything after this line runs with the network dead.
151			await page.evaluate(
