// Level-triggered recovery for a swap that never reached playback: an
// autoplay chapter chain that hits a dead network ends in a paused
// element with NETWORK_NO_SOURCE and no event ever scheduled again.
// Re-attempt from the chapter's network URL when connectivity comes
// back ('online') or the user looks at the page ('visible'). Bounded
// by trigger frequency; a successful `playing` clears the intent.
const retryPendingAutoplay = (reason: string): void => {
  if (!pendingAutoplay) return;
  if (!audio.paused) return;
  if (typeof navigator !== "undefined" && navigator.onLine === false) {
    return;
