import { createServer } from "node:http";
import puppeteer from "puppeteer";

// Minimal valid 1s silent WAV (8kHz mono 16-bit).
function silentWav(seconds = 1) {
	const sampleRate = 8000;
	const dataBytes = sampleRate * seconds * 2;
	const buf = Buffer.alloc(44 + dataBytes);
	buf.write("RIFF", 0);
	buf.writeUInt32LE(36 + dataBytes, 4);
	buf.write("WAVE", 8);
	buf.write("fmt ", 12);
	buf.writeUInt32LE(16, 16);
	buf.writeUInt16LE(1, 20);
	buf.writeUInt16LE(1, 22);
	buf.writeUInt32LE(sampleRate, 24);
	buf.writeUInt32LE(sampleRate * 2, 28);
	buf.writeUInt16LE(2, 32);
	buf.writeUInt16LE(16, 34);
	buf.write("data", 36);
	buf.writeUInt32LE(dataBytes, 40);
	return buf;
}

const wav = silentWav();
const server = createServer((req, res) => {
	if (req.url.startsWith("/audio")) {
		res.writeHead(200, {
			"content-type": "audio/wav",
			"content-length": wav.length,
		});
		res.end(wav);
	} else {
		res.writeHead(200, { "content-type": "text/html" });
		res.end("<html><body><audio id='a'></audio></body></html>");
	}
});
await new Promise((r) => server.listen(8787, r));

const browser = await puppeteer.launch({
	headless: true,
	executablePath: "/usr/bin/google-chrome",
	args: ["--no-sandbox"],
});

async function probeLoad(page, label, n) {
	await page.evaluate((i) => {
		const a = document.getElementById("a");
		a.src = `/audio?v=${i}`;
		a.load();
	}, n);
	await new Promise((r) => setTimeout(r, 1500));
	const state = await page.evaluate(() => {
		const a = document.getElementById("a");
		return {
			readyState: a.readyState,
			networkState: a.networkState,
			error: a.error ? a.error.code : null,
		};
	});
	console.log(label, JSON.stringify(state));
	return state;
}

// 1. Fetch interception
{
	const page = await browser.newPage();
	await page.goto("http://localhost:8787/");
	await page.setRequestInterception(true);
	page.on("request", (req) => {
		if (req.url().includes("/audio")) {
			console.log("  intercepted:", req.resourceType(), req.url());
			req.abort("failed").catch(() => {});
		} else req.continue().catch(() => {});
	});
	await probeLoad(page, "fetch-interception:", 1);
	await page.close();
}

// 2. Network.setBlockedURLs
{
	const page = await browser.newPage();
	await page.goto("http://localhost:8787/");
	const client = await page.createCDPSession();
	await client.send("Network.enable");
	await client.send("Network.setBlockedURLs", { urls: ["*audio*"] });
	await probeLoad(page, "setBlockedURLs:    ", 2);
	await page.close();
}

// 3. Offline emulation
{
	const page = await browser.newPage();
	await page.goto("http://localhost:8787/");
	await page.setOfflineMode(true);
	await probeLoad(page, "offline-emulation: ", 3);
	await page.close();
}

await browser.close();
server.close();

