// Probe 2: replicate the e2e flow exactly — element already has a
// loaded src over a keep-alive connection, THEN enable interception +
// offline emulation, THEN swap src to a different URL on the same
// origin. Does the new media load slip through?
import { createServer } from "node:http";
import puppeteer from "puppeteer";

function silentWav(seconds = 1) {
	const sampleRate = 8000;
	const dataBytes = sampleRate * seconds * 2;
	const buf = Buffer.alloc(44 + dataBytes);
	buf.write("RIFF", 0);
	buf.writeUInt32LE(36 + dataBytes, 4);
	buf.write("WAVE", 8);
	buf.write("fmt ", 12);
	buf.writeUInt16LE(1, 20);
	buf.writeUInt16LE(1, 22);
	buf.writeUInt32LE(sampleRate, 24);
	buf.writeUInt32LE(sampleRate * 2, 28);
	buf.writeUInt16LE(2, 32);
	buf.writeUInt16LE(16, 34);
	buf.write("data", 36);
	buf.writeUInt32LE(dataBytes, 40);
	return buf;
}

const wav = silentWav();
const hits = [];
const server = createServer((req, res) => {
	hits.push(req.url);
	if (req.url.startsWith("/chapters/")) {
		res.writeHead(200, {
			"content-type": "audio/wav",
			"content-length": wav.length,
			"accept-ranges": "bytes",
		});
		res.end(wav);
	} else {
		res.writeHead(200, { "content-type": "text/html" });
		res.end("<html><body><audio id='a'></audio></body></html>");
	}
});
await new Promise((r) => server.listen(8787, r));

const browser = await puppeteer.launch({
	headless: true,
	executablePath: "/usr/bin/google-chrome",
	args: ["--no-sandbox"],
});
// Mimic the suite: incognito context off a shared browser.
const ctx = await browser.createBrowserContext();
const page = await ctx.newPage();
page.on("console", (m) => console.log("  [page]", m.text()));
await page.goto("http://localhost:8787/");

// Step 1: load chapter 1's audio normally (keep-alive connection).
await page.evaluate(() => {
	const a = document.getElementById("a");
	a.src = "/chapters/1/audio";
	a.load();
});
await page.waitForFunction(
	() => document.getElementById("a").readyState >= 1,
	{ timeout: 5000 },
);
console.log("ch1 loaded ok");

// Step 2: enable interception + block + offline (same order as test).
await page.setRequestInterception(true);
page.on("request", (req) => {
	if (req.url().includes("/chapters/3/audio")) {
		console.log("  intercepted+aborted:", req.resourceType());
		req.abort("failed").catch(() => {});
	} else req.continue().catch(() => {});
});
await page.setOfflineMode(true);
await page.waitForFunction(() => navigator.onLine === false, {
	timeout: 5000,
});

// Step 3: swap src to chapter 3 and play (what swapToChapter does).
await page.evaluate(() => {
	const a = document.getElementById("a");
	a.src = "/chapters/3/audio";
	a.load();
	a.play().catch((e) => console.log("play rejected:", e.name));
});
await new Promise((r) => setTimeout(r, 2000));
const state = await page.evaluate(() => {
	const a = document.getElementById("a");
	return {
		readyState: a.readyState,
		networkState: a.networkState,
		error: a.error ? a.error.code : null,
		paused: a.paused,
	};
});
console.log("after blocked swap:", JSON.stringify(state));
console.log("server hits:", JSON.stringify(hits));

await browser.close();
server.close();

