// entirely — the commute dead-zone regime. setOfflineMode drives
// navigator.onLine + the online/offline events (what the hook's
// recovery listens to), but chromium MEDIA loads bypass its network
// emulation — so the audio request must be blocked explicitly via
// request interception or the "offline" element loads just fine.
await page.evaluate(() => {
	window.liveSocket.disconnect();
	window.liveSocket.connect = () => {};
});
await page.waitForFunction(() => !window.liveSocket.isConnected(), {
	timeout: 5000,
});
await page.setRequestInterception(true);
page.on("request", (req) => {
	const blocked =
		blockedAudioPath !== null && req.url().includes(blockedAudioPath);
	interceptions.push(
		`${blocked ? "ABORT" : "pass"} ${req.resourceType()} ${req.url()}`,
	);
	if (blocked) {
		req.abort("failed").catch(() => {});
	} else {
