1	// Confirmed-delivery HTTP flush shared by the progress and player-event
2	// buffers.
3	//
4	// Why this exists: both buffers used to flush with `navigator.sendBeacon`
5	// and clear their localStorage backlog when it returned `true`. But
6	// `true` only means the browser QUEUED the request — offline, the beacon
7	// is silently dropped and the data is gone. The 2026-06-11 incident lost
8	// its entire offline forensic window (heartbeats, the chapter-ended
9	// trace, the final progress pivots) to exactly this. Delivery is only
10	// delivery when the server says 2xx.
11	//
12	// Contract: POST the entries in chunks (keepalive requests share a 64KB
13	// in-flight quota per origin — one big body can be rejected outright),
14	// resolve with the entries that got a 2xx. Callers remove exactly those
15	// from their backlog and keep the rest for the next trigger (visibility
16	// change, network back online, next mount) or until their prune window
17	// expires them. sendBeacon remains useful as a last-gasp pagehide
18	// fallback — fired WITHOUT clearing, since its outcome is unknowable.
19	
20	const FLUSH_CHUNK_SIZE = 100;
21	
22	export async function flushConfirmed<T>(
23	  url: string,
24	  payloadKey: string,
25	  entries: ReadonlyArray<T>,
26	): Promise<ReadonlyArray<T>> {
27	  const delivered: T[] = [];
28	  for (let i = 0; i < entries.length; i += FLUSH_CHUNK_SIZE) {
29	    const chunk = entries.slice(i, i + FLUSH_CHUNK_SIZE);
30	    try {
31	      const res = await fetch(url, {
32	        method: "POST",
33	        keepalive: true,
34	        headers: { "content-type": "application/json" },
35	        body: JSON.stringify({ [payloadKey]: chunk }),
36	      });
37	      if (!res.ok) break;
38	      delivered.push(...chunk);
39	    } catch {
40	      // Network failure — keep this chunk and everything after it.
41	      break;
42	    }
43	  }
44	  return delivered;
45	}
46	
47	export function beaconBestEffort(
48	  url: string,
49	  payloadKey: string,
50	  entries: ReadonlyArray<unknown>,
51	): void {
52	  if (entries.length === 0) return;
53	  if (typeof navigator === "undefined" || !navigator.sendBeacon) return;
54	  const body = new Blob([JSON.stringify({ [payloadKey]: entries })], {
55	    type: "application/json",
56	  });
57	  navigator.sendBeacon(url, body);
58	}
59

